=head2 Google::Cloud::Alloydb::V1alpha::Resources::AutomatedBackupPolicy

Message describing the user-specified automated backup policy.

All fields in the automated backup policy are optional. Defaults for each
field are provided if they are not set.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->weekly_schedule() >> / C<< $msg->weekly_schedule($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1alpha::Resources::AutomatedBackupPolicy::WeeklySchedule>)

Weekly schedule for the Backup.

=item * C<< $msg->time_based_retention() >> / C<< $msg->time_based_retention($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1alpha::Resources::AutomatedBackupPolicy::TimeBasedRetention>)

Time-based Backup retention policy.

=item * C<< $msg->quantity_based_retention() >> / C<< $msg->quantity_based_retention($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1alpha::Resources::AutomatedBackupPolicy::QuantityBasedRetention>)

Quantity-based Backup retention policy to retain recent backups.

=item * C<< $msg->enabled() >> / C<< $msg->enabled($value) >>

Type: C<Bool>

Whether automated automated backups are enabled. If not set, defaults to
true.

=item * C<< $msg->backup_window() >> / C<< $msg->backup_window($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

The length of the time window during which a backup can be
taken. If a backup does not succeed within this time window, it will be
canceled and considered failed.

The backup window must be at least 5 minutes long. There is no upper bound
on the window. If not set, it defaults to 1 hour.

=item * C<< $msg->encryption_config() >> / C<< $msg->encryption_config($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1alpha::Resources::EncryptionConfig>)

Optional. The encryption config can be specified to encrypt the
backups with a customer-managed encryption key (CMEK). When this field is
not specified, the backup will use the cluster's encryption config.

=item * C<< $msg->location() >> / C<< $msg->location($value) >>

Type: C<String>

The location where the backup will be stored. Currently, the only supported
option is to store the backup in the same region as the cluster.

If empty, defaults to the region of the cluster.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1alpha::Resources::AutomatedBackupPolicy::LabelsEntry>)

Labels to apply to backups created using this configuration.

=back

=head2 Google::Cloud::Alloydb::V1alpha::Resources::ContinuousBackupConfig

ContinuousBackupConfig describes the continuous backups recovery
configurations of a cluster.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->enabled() >> / C<< $msg->enabled($value) >>

Type: C<Bool>

Whether ContinuousBackup is enabled.

=item * C<< $msg->recovery_window_days() >> / C<< $msg->recovery_window_days($value) >>

Type: C<Int32>

The number of days that are eligible to restore from using PITR. To support
the entire recovery window, backups and logs are retained for one day more
than the recovery window. If not set, defaults to 14 days.

=item * C<< $msg->encryption_config() >> / C<< $msg->encryption_config($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1alpha::Resources::EncryptionConfig>)

The encryption config can be specified to encrypt the
backups with a customer-managed encryption key (CMEK). When this field is
not specified, the backup will use the cluster's encryption config.

=back

=head2 Google::Cloud::Alloydb::V1alpha::Resources::ContinuousBackupInfo

ContinuousBackupInfo describes the continuous backup properties of a
cluster.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->encryption_info() >> / C<< $msg->encryption_info($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1alpha::Resources::EncryptionInfo>)

Output only. The encryption information for the WALs and backups required
for ContinuousBackup.

=item * C<< $msg->enabled_time() >> / C<< $msg->enabled_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. When ContinuousBackup was most recently enabled. Set to null
if ContinuousBackup is not enabled.

=item * C<< $msg->schedule() >> / C<< $msg->schedule($value) >>

Type: C<Enum> (L<Google::Type::DayOfWeek>)

Output only. Days of the week on which a continuous backup is taken.

=item * C<< $msg->earliest_restorable_time() >> / C<< $msg->earliest_restorable_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The earliest restorable time that can be restored to. If
continuous backups and recovery was recently enabled, the earliest
restorable time is the creation time of the earliest eligible backup within
this cluster's continuous backup recovery window. After a cluster has had
continuous backups enabled for the duration of its recovery window, the
earliest restorable time becomes "now minus the recovery window". For
example, assuming a point in time recovery is attempted at 04/16/2025
3:23:00PM with a 14d recovery window, the earliest restorable time would be
04/02/2025 3:23:00PM. This field is only visible if the
CLUSTER_VIEW_CONTINUOUS_BACKUP cluster view is provided.

=back

