=head2 Google::Cloud::Alloydb::V1alpha::Resources::Instance

An Instance is a computing unit that an end customer can connect to.
It's the main unit of computing resources in AlloyDB.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Output only. The name of the instance resource with the format:
 * projects/{project}/locations/{region}/clusters/{cluster_id}/instances/{instance_id}
where the cluster and instance ID segments should satisfy the regex
expression `[a-z]([a-z0-9-]{0,61}[a-z0-9])?`, e.g. 1-63 characters of
lowercase letters, numbers, and dashes, starting with a letter, and ending
with a letter or number. For more details see https://google.aip.dev/122.
The prefix of the instance resource name is the name of the parent
resource:
 * projects/{project}/locations/{region}/clusters/{cluster_id}

=item * C<< $msg->display_name() >> / C<< $msg->display_name($value) >>

Type: C<String>

User-settable and human-readable display name for the Instance.

=item * C<< $msg->uid() >> / C<< $msg->uid($value) >>

Type: C<String>

Output only. The system-generated UID of the resource. The UID is assigned
when the resource is created, and it is retained until it is deleted.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Create time stamp

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Update time stamp

=item * C<< $msg->delete_time() >> / C<< $msg->delete_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Delete time stamp

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1alpha::Resources::Instance::LabelsEntry>)

Labels as key value pairs

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1alpha::Instance::State>)

Output only. The current serving state of the instance.

=item * C<< $msg->instance_type() >> / C<< $msg->instance_type($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1alpha::Instance::InstanceType>)

Required. The type of the instance. Specified at creation time.

=item * C<< $msg->machine_config() >> / C<< $msg->machine_config($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1alpha::Resources::Instance::MachineConfig>)

Configurations for the machines that host the underlying
database engine.

=item * C<< $msg->availability_type() >> / C<< $msg->availability_type($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1alpha::Instance::AvailabilityType>)

Availability type of an Instance.
If empty, defaults to REGIONAL for primary instances.
For read pools, availability_type is always UNSPECIFIED. Instances in the
read pools are evenly distributed across available zones within the region
(i.e. read pools with more than one node will have a node in at
least two zones).

=item * C<< $msg->gce_zone() >> / C<< $msg->gce_zone($value) >>

Type: C<String>

The Compute Engine zone that the instance should serve from, per
https://cloud.google.com/compute/docs/regions-zones
This can ONLY be specified for ZONAL instances.
If present for a REGIONAL instance, an error will be thrown.
If this is absent for a ZONAL instance, instance is created in a random
zone with available capacity.

=item * C<< $msg->database_flags() >> / C<< $msg->database_flags($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1alpha::Resources::Instance::DatabaseFlagsEntry>)

Database flags. Set at the instance level.
They are copied from the primary instance on secondary instance creation.
Flags that have restrictions default to the value at primary
instance on read instances during creation. Read instances can set new
flags or override existing flags that are relevant for reads, for example,
for enabling columnar cache on a read instance. Flags set on read instance
might or might not be present on the primary instance.


This is a list of "key": "value" pairs.
"key": The name of the flag. These flags are passed at instance setup time,
so include both server options and system variables for Postgres. Flags are
specified with underscores, not hyphens.
"value": The value of the flag. Booleans are set to B<on> for true
and B<off> for false. This field must be omitted if the flag
doesn't take a value.

=item * C<< $msg->writable_node() >> / C<< $msg->writable_node($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1alpha::Resources::Instance::Node>)

Output only. This is set for the read-write VM of the PRIMARY instance
only.

=item * C<< $msg->nodes() >> / C<< $msg->nodes($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1alpha::Resources::Instance::Node>)

Output only. List of available read-only VMs in this instance, including
the standby for a PRIMARY instance.

=item * C<< $msg->query_insights_config() >> / C<< $msg->query_insights_config($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1alpha::Resources::Instance::QueryInsightsInstanceConfig>)

Configuration for query insights.

=item * C<< $msg->query_insights_info() >> / C<< $msg->query_insights_info($value) >>

