=item * C<< $msg->outbound_public_ip_addresses() >> / C<< $msg->outbound_public_ip_addresses($value) >>

Type: C<String>

Output only. All outbound public IP addresses configured for the instance.

=item * C<< $msg->activation_policy() >> / C<< $msg->activation_policy($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1alpha::Instance::ActivationPolicy>)

Optional. Specifies whether an instance needs to spin up. Once the instance
is active, the activation policy can be updated to the `NEVER` to stop the
instance. Likewise, the activation policy can be updated to `ALWAYS` to
start the instance.
There are restrictions around when an instance can/cannot be activated (for
example, a read pool instance should be stopped before stopping primary
etc.). Please refer to the API documentation for more details.

