=head2 Google::Cloud::Alloydb::V1alpha::Resources::SupportedDatabaseFlag

SupportedDatabaseFlag gives general information about a database flag,
like type and allowed values. This is a static value that is defined
on the server side, and it cannot be modified by callers.
To set the Database flags on a particular Instance, a caller should modify
the Instance.database_flags field.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->string_restrictions() >> / C<< $msg->string_restrictions($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1alpha::Resources::SupportedDatabaseFlag::StringRestrictions>)

Restriction on STRING type value.

=item * C<< $msg->integer_restrictions() >> / C<< $msg->integer_restrictions($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1alpha::Resources::SupportedDatabaseFlag::IntegerRestrictions>)

Restriction on INTEGER type value.

=item * C<< $msg->recommended_string_value() >> / C<< $msg->recommended_string_value($value) >>

Type: C<String>

The recommended value for a STRING flag.

=item * C<< $msg->recommended_integer_value() >> / C<< $msg->recommended_integer_value($value) >>

Type: C<Message> (L<Google::Protobuf::Wrappers::Int64Value>)

The recommended value for an INTEGER flag.

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

The name of the flag resource, following Google Cloud conventions, e.g.:
 * projects/{project}/locations/{location}/flags/{flag}
This field currently has no semantic meaning.

=item * C<< $msg->flag_name() >> / C<< $msg->flag_name($value) >>

Type: C<String>

The name of the database flag, e.g. "max_allowed_packets".
The is a possibly key for the Instance.database_flags map field.

=item * C<< $msg->value_type() >> / C<< $msg->value_type($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1alpha::SupportedDatabaseFlag::ValueType>)

=item * C<< $msg->accepts_multiple_values() >> / C<< $msg->accepts_multiple_values($value) >>

Type: C<Bool>

Whether the database flag accepts multiple values. If true,
a comma-separated list of stringified values may be specified.

=item * C<< $msg->supported_db_versions() >> / C<< $msg->supported_db_versions($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1alpha::DatabaseVersion>)

Major database engine versions for which this flag is supported.

=item * C<< $msg->requires_db_restart() >> / C<< $msg->requires_db_restart($value) >>

Type: C<Bool>

Whether setting or updating this flag on an Instance requires a database
restart. If a flag that requires database restart is set, the backend
will automatically restart the database (making sure to satisfy any
availability SLO's).

=item * C<< $msg->scope() >> / C<< $msg->scope($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1alpha::SupportedDatabaseFlag::Scope>)

The scope of the flag.

=back

